// the golden rule, in one line:
// BAD:  store "hunter2"
// GOOD: store a one-way hash of "hunter2"

// login without ever seeing the real password
const stored = hashPassword("hunter2"); // saved at signup
function login(attempt) {
  return hashPassword(attempt) === stored; // compare fingerprints
}
console.log(login("hunter2")); // true
console.log(login("wrong"));   // false

// same password + different salt = different hash
hashPassword("hunter2", "salt-A9f2"); // -> "c41d…"
hashPassword("hunter2", "salt-Q7x1"); // -> "9be0…" (totally different)

// sessions expire — old wristbands stop working
function isSessionValid(session) {
  return Date.now() < session.expiresAt;
}

// safe reset link: single-use + expires fast
const reset = {
  token: "one-time-code",
  expiresAt: Date.now() + 60 * 60 * 1000, // 1 hour, then dead
  used: false,
};
